{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Extracorporeal membrane oxygenation (ECMO) for refractory cardiac arrest (RCA, ECPR) provides adequate systemic perfusion while the underlying cause may be diagnosed and treated. Whilst promising outcomes have been reported [1-3], survival rates vary widely [3] which is likely due to differences in study design, geographical *Correspondence: mark.dennis@sydney.edu.au † Sameer Karve and Dominique Lahood have contributed equally to this work 1 Sydney Medical School, University of Sydney, Sydney, NSW, Australia Full list of author information is available at the end of the article All authors take responsibility for all aspects of the reliability and freedom from bias of the data presented and their discussed interpretation",
      "reason": "The background describes current knowledge (ECMO provides perfusion; promising outcomes reported) and notes important uncertainty—wide variation in survival likely due to differences in study design and geography."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background: The use of extracorporeal membrane oxygenation (ECMO) during cardiac arrest (ECPR) has increased exponentially. However, reported outcomes vary considerably due to differing study designs and selection criteria. This review assessed the impact of pre-defined selection criteria on ECPR survival.",
      "reason": "The abstract explicitly states the variability in reported outcomes and frames the review's purpose to assess the impact of selection criteria, explaining the importance and need for the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided that discusses existing similar systematic reviews, nor is there explanation of the need for this review relative to prior reviews or citations of previous reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Extracorporeal membrane oxygenation (ECMO) for refractory cardiac arrest (RCA, ECPR) provides adequate systemic perfusion while the underlying cause may be diagnosed and treated.",
      "reason": "This statement briefly describes the proposed mechanism of action of the intervention (ECMO provides systemic perfusion to allow diagnosis and treatment), satisfying the requirement for intervention mechanism description."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or diagram showing hypothesised relationships between intervention components and outcomes is provided or referenced in the retrieved evidence."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "We sought to analyse the survival rates in ECPR studies that had defined inclusion criteria for refractory out of hospital cardiac arrest (OHCA) and in hospital cardiac arrest (IHCA). Further, we sought to examine the association between the use of prospectively determined selection criteria (as opposed to retrospective no inclusion criteria) and the number of these inclusion criteria on reported survival outcomes.",
      "reason": "The review objectives are explicitly stated (to analyse survival rates and examine associations of selection criteria and study design with outcomes), but they are not presented using an explicit question-formulation framework (e.g., PICO) in the provided evidence."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Two reviewers using a pre-defined standardised data extraction form, extracted data as pertinent to the PICO. Data items included general study information (author, date, study design), cohort demographics (age, gender, comorbidities), arrest specifics (OHCA, IHCA, aetiology), inclusion criteria (total number, age, rhythm, time to ECMO flow, lactate, ETCO2) and outcomes (best Cerebral Performance Category (CPC) status, survival).",
      "reason": "The manuscript indicates data extraction was 'as pertinent to the PICO' and lists population and outcomes, but it does not explicitly state planned comparisons framed as PICO (e.g., explicit intervention vs comparator statements) in the provided evidence."
    }
  ],
  "confidence": "80"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We used the PICO (Population, Intervention, Comparison, Outcome) search format: Among adults with cardiac arrest in any setting (OHCA or IHCA) who qualify for ECPR by inclusion and exclusion parameters outlined (P), does receiving ECPR, including ECMO or cardiopulmonary bypass, during cardiac arrest (I), compared to manual CPR and/or mechanical CPR (C) without any mechanical circulatory support, change meaningful outcomes (favourable neurological status or survival at study end) (O). Contemporary studies from January 2000 to June 2021 were included. Only English language studies were included. Randomised trials, non-randomised controlled trials, and observational studies (cohort studies and casecontrol studies) were included. The population included adults (age above 12) with IHCA or OHCA of any origin. Animal studies, ecological studies, case reports, reviews, abstracts, editorials, comments, and letters to the editor were excluded. Studies with ≤ 5 patients receiving ECPR or studies that did not report the inclusion or exclusion criteria regarding the eligibility of ECPR or the timing of ECPR (i.e. during or after cardiac arrest) were excluded. The primary outcome of interest was favourable neurological outcomes on discharge, using study-specified definitions.",
      "reason": "The Methods explicitly list PICO components, eligible study designs, settings (OHCA/IHCA), age threshold (>12), date range, and specific exclusions (study types, small sample size, lack of reported inclusion/exclusion criteria), covering study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Contemporary studies from January 2000 to June 2021 were included. Only English language studies were included. Randomised trials, non-randomised controlled trials, and observational studies (cohort studies and casecontrol studies) were included. ... Animal studies, ecological studies, case reports, reviews, abstracts, editorials, comments, and letters to the editor were excluded.",
      "reason": "The Methods specify date limits (2000–June 2021), language restriction (English), and types of reports included/excluded (e.g., abstracts excluded), which addresses report-characteristic eligibility."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported is present in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Results are reported separately for pre-defined subgroups based on type of study (retrospective or prospective), and the location of cardiac arrest (IHCA vs OHCA).",
      "reason": "The Methods describe subgroup definitions used in synthesis (prospective vs retrospective; IHCA vs OHCA) that link to the comparisons/objectives described earlier (e.g., effect of prospectively determined selection criteria vs retrospective)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided in the available evidence for notable restrictions (e.g., why the year range or English-only restriction was chosen)."
    }
  ],
  "confidence": 85
}

